//! Std-only smoke run of the `firewall_gw_packet` libFuzzer target
//! (`fuzz/fuzz_targets/`): the same harness (`fuzz/harness/firewall_gw_packet.rs`,
//! included by path) driven by the deterministic mutator in
//! `fuzz/harness/smoke.rs` over the committed seed corpus. See
//! `fuzz/README.md`. `ROBODR_FUZZ_ITERS` / `ROBODR_FUZZ_SECS` tune the run.
//!
//! The seeds are (re)generated by `regenerate_seeds` (run with
//! `--ignored`).

#[path = "../../../fuzz/harness/firewall_gw_packet.rs"]
mod firewall_gw_packet;
#[path = "../../../fuzz/harness/smoke.rs"]
mod smoke;

use firewall_gw_packet::record;
use robodr_cdr::Representation;
use robodr_firewall_gw::lowcmd::{self, LowCmdCodec, WireMotor};
use robodr_firewall_gw::rtps::build::Datagram;
use robodr_firewall_gw::testkit::*;
use robodr_firewall_gw::{legacy, sport};

const DIR: &str = env!("CARGO_MANIFEST_DIR");

fn seeds() -> Vec<(&'static str, Vec<u8>)> {
    let mut out = Vec::new();
    for (name, fx, flags) in [
        ("seed-g1-stream.bin", Fixture::G1, 0u8),
        ("seed-go2-stream.bin", Fixture::Go2, 1),
    ] {
        let spec = lowcmd_spec(fx);
        let pins = (spec.pinned_mode_pr, spec.pinned_mode_machine);
        let c = codec(fx);
        let mut v = vec![flags];
        let good = mid_frame(c, &spec.motors, 0.0, pins);
        let mut bad = good;
        let mut w: WireMotor = bad.motor(0).unwrap();
        w.tau = 1e4;
        bad.set_motor(0, w);
        bad.seal();
        let rep = if fx == Fixture::G1 {
            Representation::CdrLe
        } else {
            Representation::Cdr2Le
        };
        let sedp = sedp_datagram(PREFIX, WRITER, "rt/lowcmd", c.dds_type_name());
        v.extend(record(0, &sedp));
        v.extend(record(0, &lowcmd_datagram(PREFIX, WRITER, 1, &good, rep)));
        v.extend(record(0, &lowcmd_datagram(PREFIX, WRITER, 2, &bad, rep)));
        v.extend(record(1, &lowcmd_datagram(FOREIGN, WRITER, 1, &good, rep)));
        let payload = lowcmd::encode_payload(&good, rep);
        let frag = Datagram::new(PREFIX)
            .data_frag(WRITER, 3, 1, 256, payload.len() as u32, &payload[..256])
            .finish();
        v.extend(record(4, &frag));
        v.extend(record(0, &lowcmd_datagram(PREFIX, WRITER, 2, &good, rep)));
        if fx == Fixture::Go2 {
            let req = sport::encode_request(
                Representation::CdrLe,
                1,
                1008,
                r#"{"x":1.4000000000,"y":0.0,"z":0.2000000000}"#,
            );
            let d = Datagram::new(PREFIX)
                .data(SPORT_WRITER, 1, &[], &req)
                .finish();
            v.extend(record(0, &d));
            v.extend(record(2, &legacy::build_high(2, 1.2, 0.0, 0.1)));
            v.extend(record(
                3,
                &legacy::build_low(&[(0x0A, [0.0, 0.0, 30.0, 20.0, 1.0])]),
            ));
        }
        out.push((name, v));
    }
    out.push(("seed-hg-only.bin", {
        let spec = lowcmd_spec(Fixture::G1);
        let m = mid_frame(
            LowCmdCodec::Hg,
            &spec.motors,
            1.0,
            (spec.pinned_mode_pr, spec.pinned_mode_machine),
        );
        let mut v = vec![2u8];
        v.extend(record(
            0,
            &lowcmd_datagram(PREFIX, WRITER, 7, &m, Representation::CdrBe),
        ));
        v
    }));
    out
}

#[test]
#[ignore = "regenerates fuzz/corpus/firewall_gw_packet"]
fn regenerate_seeds() {
    let dir = smoke::corpus_dir(DIR, "firewall_gw_packet");
    std::fs::create_dir_all(&dir).unwrap();
    for (name, bytes) in seeds() {
        std::fs::write(dir.join(name), bytes).unwrap();
    }
}

#[test]
fn committed_seeds_match_the_generator() {
    let committed = smoke::corpus(DIR, "firewall_gw_packet");
    assert!(!committed.is_empty(), "no committed seeds");
    for (_, s) in seeds() {
        assert!(
            committed.contains(&s),
            "a seed changed: run regenerate_seeds"
        );
    }
}

#[test]
fn firewall_gw_packet_smoke() {
    let mut seeds: Vec<Vec<u8>> = smoke::corpus(DIR, "firewall_gw_packet");
    seeds.extend(self::seeds().into_iter().map(|(_, s)| s));
    smoke::run(
        "firewall_gw_packet",
        &seeds,
        0x6a7e_0001,
        &firewall_gw_packet::run,
    );
}
